package com.aichangeguard.testing.model;

import com.fasterxml.jackson.annotation.JsonInclude;

import java.time.Instant;
import java.util.List;

/**
 * Complete structured report generated by the Test Intelligence Engine.
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record TestSelectionReport(
        String repositoryPath,
        String baseRevision,
        String targetRevision,
        int totalDiscoveredTests,
        int totalDiscoveredTestClasses,
        List<SelectedTest> selectedTests,
        List<TestCase> unselectedTests,
        List<UnresolvedTestMapping> unresolvedMappings,
        boolean isFallbackTriggered,
        FallbackReason fallbackReason,
        String fallbackExplanation,
        List<String> changedSymbols,
        Instant analyzedAt,
        List<String> warnings,
        List<String> limitations
) {
    public int selectedCount() {
        return selectedTests != null ? selectedTests.size() : 0;
    }

    public int unselectedCount() {
        return unselectedTests != null ? unselectedTests.size() : 0;
    }

    public int unresolvedCount() {
        return unresolvedMappings != null ? unresolvedMappings.size() : 0;
    }
}

